#include <bits/stdc++.h>
using namespace std;
const int mod=1e9+7;
void solve()
{
    vector<int>a(6),b(6);
    map<int,int>mp1;
    for(int i=0;i<6;i++){
        cin>>a[i];
        mp1[a[i]]++;
    }
    for(int i=0;i<6;i++){
        cin>>b[i];
        mp1[b[i]]++;
    }
    int x,y;
    cin>>x>>y;
    if(mp1[y]<x){
        cout<<"win"<<endl;
    }
    else{
        cout<<"lose"<<endl;
    }
}
signed main()
{
    int t;
    cin>>t;
    while(t--){
        solve();
    }
    return 0;
}